use "./sim.ts" { makeBall, makeBalls, step, draw }

page Sim "/" {
  state count = 5
  state frames = 0
  state paused = false
  computed pauseLabel = paused ? "Reanudar" : "Pausar"
  ref box
  ref balls
  ref raf

  fn render() {
    draw(box.getContext("2d"), balls, 400, 300)
  }

  fn loop() {
    step(balls, 400, 300)
    render()
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn add() {
    balls.push(makeBall(balls, 400, 300))
    count = balls.length
    if paused {
      render()
    }
  }

  fn toggle() {
    paused = !paused
    if paused {
      cancelAnimationFrame(raf)
    } else {
      raf = requestAnimationFrame(loop)
    }
  }

  fn reset() {
    balls = makeBalls(5, 400, 300)
    count = balls.length
    frames = 0
    if paused {
      render()
    }
  }

  mount {
    balls = makeBalls(5, 400, 300)
    count = balls.length
    raf = requestAnimationFrame(loop)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 align=start {
    title "Simulación de pelotas" tag=h1
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc; background: #fff"
    row gap=2 {
      button "Agregar" primary -> add()
      button pauseLabel -> toggle()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}

