export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
  color: string;
}

const R = 10;
const GRAVITY = 0.2;
const COLORS = ["#e11d48", "#2563eb", "#16a34a", "#d97706", "#7c3aed", "#0891b2", "#db2777"];

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function makeBall(existing: Ball[], w: number, h: number): Ball {
  let x = rand(R, w - R);
  let y = rand(R, h - R);
  for (let attempt = 0; attempt < 100; attempt++) {
    const free = existing.every((b) => Math.hypot(b.x - x, b.y - y) >= b.r + R);
    if (free) break;
    x = rand(R, w - R);
    y = rand(R, h - R);
  }
  return {
    x,
    y,
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    r: R,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeBalls(n: number, w: number, h: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(makeBall(balls, w, h));
  return balls;
}

function clampToWalls(b: Ball, w: number, h: number): void {
  if (b.x < b.r) {
    b.x = b.r;
    b.vx = Math.abs(b.vx);
  } else if (b.x > w - b.r) {
    b.x = w - b.r;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y < b.r) {
    b.y = b.r;
    b.vy = Math.abs(b.vy);
  } else if (b.y > h - b.r) {
    b.y = h - b.r;
    b.vy = -Math.abs(b.vy);
  }
}

export function step(balls: Ball[], w: number, h: number): void {
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;
    clampToWalls(b, w, h);
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      const minDist = a.r + b.r;
      if (dist < minDist) {
        const nx = dist === 0 ? 1 : dx / dist;
        const ny = dist === 0 ? 0 : dy / dist;
        const approaching = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny < 0;
        if (approaching) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
        const overlap = (minDist - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        clampToWalls(a, w, h);
        clampToWalls(b, w, h);
      }
    }
  }
}

export function draw(ctx: CanvasRenderingContext2D, balls: Ball[], w: number, h: number): void {
  ctx.clearRect(0, 0, w, h);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

export type Ball = { x: number; y: number; vx: number; vy: number; r: number };

export const W = 400;
export const H = 300;
export const R = 10;
export const GRAVITY = 0.2;

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function makeBall(balls: Ball[] = [], w: number = W, h: number = H): Ball {
  let b: Ball = { x: 0, y: 0, vx: 0, vy: 0, r: R };
  for (let tries = 0; tries < 50; tries++) {
    b = {
      x: rand(R, w - R),
      y: rand(R, h - R),
      vx: rand(-3, 3),
      vy: rand(-3, 3),
      r: R,
    };
    const overlaps = balls.some((o) => Math.hypot(o.x - b.x, o.y - b.y) < o.r + b.r);
    if (!overlaps) break;
  }
  return b;
}

export function makeBalls(n: number, w: number = W, h: number = H): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(makeBall(balls, w, h));
  return balls;
}

export function step(balls: Ball[], w: number = W, h: number = H): void {
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x - b.r < 0) {
      b.x = b.r;
      b.vx = Math.abs(b.vx);
    } else if (b.x + b.r > w) {
      b.x = w - b.r;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y - b.r < 0) {
      b.y = b.r;
      b.vy = Math.abs(b.vy);
    } else if (b.y + b.r > h) {
      b.y = h - b.r;
      b.vy = -Math.abs(b.vy);
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      let dist = Math.hypot(dx, dy);
      const min = a.r + b.r;
      if (dist < min) {
        // intercambio de velocidades (colisión elástica, masas iguales)
        const tvx = a.vx;
        const tvy = a.vy;
        a.vx = b.vx;
        a.vy = b.vy;
        b.vx = tvx;
        b.vy = tvy;
        // separarlas para que no queden pegadas
        let nx = 1;
        let ny = 0;
        if (dist > 0.0001) {
          nx = dx / dist;
          ny = dy / dist;
        } else {
          dist = 0;
        }
        const push = (min - dist) / 2;
        a.x -= nx * push;
        a.y -= ny * push;
        b.x += nx * push;
        b.y += ny * push;
      }
    }
  }

  // asegurar que ninguna salga del canvas tras separar
  for (const b of balls) {
    b.x = Math.min(Math.max(b.x, b.r), w - b.r);
    b.y = Math.min(Math.max(b.y, b.r), h - b.r);
  }
}

export function draw(canvas: HTMLCanvasElement | null, balls: Ball[], w: number = W, h: number = H): void {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f8fafc";
  ctx.fillRect(0, 0, w, h);
  balls.forEach((b, i) => {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = `hsl(${(i * 67) % 360}, 70%, 50%)`;
    ctx.fill();
  });
}

